"""
1. @Override
2. protected boolean calculateFrequency() {
3.     int smallestIndex = -1;
4.     int posSmall = Integer.MAX_VALUE;
5.     final int[][] pos = new int[bs.length][];
6.     for (int i = 0; i < termCount; i++) {
7.         pos[i] = bs[i].getPositions();
8.         if (pos[i].length < posSmall) {
9.             posSmall = pos[i].length;
10.             smallestIndex = i;
11.         }
12.     }
13.     frequency = 0;
14.     int[] seed = pos[smallestIndex];
15.     int[] position = new int[termCount];
16.     boolean[] found = new boolean[termCount];
17.     boolean[] end = new boolean[termCount];
18.     for (int posInSeed = 0; posInSeed < seed.length; posInSeed++) {
19.         Arrays.fill(found, false);
20.         int targetPosition = seed[posInSeed];
21.         found[smallestIndex] = true;
22.         for (int i = 0; i < termCount; i++) {
23.             if (i == smallestIndex) {
24.                 continue;
25.             }
26.             final int thisTarget = targetPosition - (smallestIndex - i);
27.             while (position[i] < pos[i].length && pos[i][position[i]] < thisTarget) {
28.                 position[i]++;
29.             }
30.             if (position[i] == pos[i].length) {
31.                 end[i] = true;
32.                 break;
33.             }
34.             if (pos[i][position[i]] == thisTarget) {
35.                 found[i] = true;
36.             }
37.         }
38.         if (allTrue(found)) {
39.             frequency++;
40.             if (positions != null) {
41.                 positions.add(pos[0][position[0]]);
42.             }
43.         } else {
44.             if (anyTrue(end)) {
45.                 break;
46.             }
47.         }
48.     }
49.     return frequency > 0;
50. }
