46.         NFAVertexND repetitionAcceptVertex = null;
47.         HashMap<NFAVertexND, NFAVertexND> stateMap = new HashMap<NFAVertexND, NFAVertexND>();
48.         for (NFAVertexND originalVertex : m.vertexSet()) {
49.             NFAVertexND newVertex = deriveVertex(resultNFA, originalVertex);
50.             stateMap.put(originalVertex, newVertex);
51.             resultNFA.addVertex(newVertex);
52.             if (m.getInitialState().equals(originalVertex)) {
53.                 repetitionInitialVertex = newVertex;
54.             }
55.             if (m.isAcceptingState(originalVertex)) {
56.                 repetitionAcceptVertex = newVertex;
57.             }
58.         }
59.         for (NFAEdge e : m.edgeSet()) {
60.             NFAVertexND source = stateMap.get(e.getSourceVertex());
61.             NFAVertexND target = stateMap.get(e.getTargetVertex());
62.             NFAEdge newEdge = new NFAEdge(source, target, e.getTransitionLabel());
63.             resultNFA.addEdge(newEdge);
64.         }
65.         NFAEdge newEdge = new NFAEdge(lastConnectingVertex, repetitionInitialVertex, continueTransitionLabel);
66.         resultNFA.addEdge(newEdge);
67.         if (i >= cmin) {
68.             if (!bounded) {
69.                 newEdge = new NFAEdge(repetitionAcceptVertex, lastConnectingVertex, continueTransitionLabel);
70.                 resultNFA.addEdge(newEdge);
71.             }
72.             if ((bounded || cmin != 0) && i == numRepetitions) {
73.                 newEdge = new NFAEdge(repetitionAcceptVertex, newAcceptVertex, new EpsilonTransitionLabel("ε1"));
74.                 resultNFA.addEdge(newEdge);
75.             } else {
76.                 if (i < numRepetitions) {
77.                     newEdge = new NFAEdge(repetitionAcceptVertex, newAcceptVertex, finishTransitionLabel);
78.                     resultNFA.addEdge(newEdge);
79.                 }
80.             }
81.         }
82.         lastConnectingVertex = repetitionAcceptVertex;
83.     }
84.     return resultNFA;
85. }
