6.     reader.beginObject();
7.     while (reader.hasNext()) {
8.         String key = reader.nextName();
9.         Operation op = null;
10.         for (Operation o : Operation.VALUES) {
11.             if (key.startsWith(o.operator)) {
12.                 op = o;
13.                 key = key.substring(o.operator.length());
14.                 break;
15.             }
16.         }
17.         ModDependency.Kind kind = ModDependency.Kind.parse(key);
18.         if (kind == null) {
19.             throw new ParseMetadataException(String.format("%s is not an allowed dependency key, must be one of: %s", key, Arrays.stream(ModDependency.Kind.values()).map(ModDependency.Kind::getKey).collect(Collectors.joining(", "))), reader);
20.         }
21.         List<ModDependency> deps = readDependencies(reader, kind);
22.         if (!deps.isEmpty() || op == Operation.REPLACE) {
23.             modOverrides.computeIfAbsent(kind, ignore -> new EnumMap<>(Operation.class)).put(op, deps);
24.         }
25.     }
26.     reader.endObject();
27.     List<Entry> ret = new ArrayList<>();
28.     for (Map.Entry<ModDependency.Kind, Map<Operation, List<ModDependency>>> entry : modOverrides.entrySet()) {
29.         ModDependency.Kind kind = entry.getKey();
30.         Map<Operation, List<ModDependency>> map = entry.getValue();
31.         List<ModDependency> values = map.get(Operation.REPLACE);
32.         if (values != null) {
33.             ret.add(new Entry(Operation.REPLACE, kind, values));
34.         } else {
35.             values = map.get(Operation.REMOVE);
36.             if (values != null) {
37.                 ret.add(new Entry(Operation.REMOVE, kind, values));
38.             }
